from pathlib import Path
import base64
import hashlib
import re

# Exact user-selected artwork, resized only to 256x256 for launcher packaging.
# Source artwork: white filmstrip + red play button + blue/purple layers + orange download arrow.
CHUNKS = [
"",
"",
"",
"",
""
]

icon_bytes = base64.b64decode("".join(CHUNKS), validate=True)
EXPECTED_SIZE = 15954
EXPECTED_SHA = "193da67e825bb528facde86d8a89dc6f9de53b8d70bdc7172d821a5177282136"
actual_sha = hashlib.sha256(icon_bytes).hexdigest()
if len(icon_bytes) != EXPECTED_SIZE or actual_sha != EXPECTED_SHA:
    raise SystemExit(f"Wrong icon bytes: size={len(icon_bytes)} sha256={actual_sha}")

res = Path("video-compressor/app/src/main/res")
# Remove any adaptive/default launcher resources if present in the checkout.
for p in [
    res / "mipmap-anydpi-v26" / "ic_launcher.xml",
    res / "mipmap-anydpi-v26" / "ic_launcher_round.xml",
    res / "drawable" / "ic_launcher_background.xml",
    res / "drawable" / "ic_launcher_foreground.xml",
]:
    if p.exists():
        p.unlink()

for density in ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"]:
    d = res / f"mipmap-{density}"
    d.mkdir(parents=True, exist_ok=True)
    (d / "ic_launcher.jpg").write_bytes(icon_bytes)
    (d / "ic_launcher_round.jpg").write_bytes(icon_bytes)

manifest = Path("video-compressor/app/src/main/AndroidManifest.xml")
s = manifest.read_text(encoding="utf-8")
s = re.sub(r'android:icon="@[^"]+"', 'android:icon="@mipmap/ic_launcher"', s, count=1)
s = re.sub(r'android:roundIcon="@[^"]+"', 'android:roundIcon="@mipmap/ic_launcher_round"', s, count=1)
manifest.write_text(s, encoding="utf-8")
print(f"Installed verified selected icon: {len(icon_bytes)} bytes sha256={actual_sha}")
